import { AfterViewInit, Directive, Injector, TemplateRef, ViewChild, inject } from '@angular/core';
import { ParamMap, Params, Router } from '@angular/router';
import { Page, emptyPage } from 'espd-common/data';
import { EspdFormGroup } from 'espd-common/forms/api';
import { MessageConfig } from 'espd-common/i18n';
import { ActionsGenerator } from 'espd-common/layout/actions';
import { ColumnDefinition } from 'espd-common/layout/table';
import { Observable, catchError, distinctUntilChanged, finalize, map, of } from 'rxjs';
import { AbstractEntityComponent } from '../abstract-entity/abstract-entity.component';
import { EntityListScaffoldComponent } from '../entity-list-scaffold/entity-list-scaffold.component';
import { Filter } from './filter.model';
import { Entity } from '../abstract-entity-detail/entity.model';

@Directive()
export abstract class AbstractEntityListComponent<T extends Entity, FilterType extends Filter> extends AbstractEntityComponent implements AfterViewInit {

	@ViewChild(EntityListScaffoldComponent)
	protected listScaffold?: EntityListScaffoldComponent;

	public form?: EspdFormGroup<any> = undefined;
	public page: Page<T> = emptyPage;
	protected router = inject(Router);

	public abstract filter: FilterType;
	public abstract columns: ColumnDefinition[];
	public abstract actionGenerator: ActionsGenerator;
	protected abstract fetchPage(filter: FilterType): Observable<Page<T>>;

	protected setupForm?(): void;
	// called when the form model has been updated and needs to be reflected on the view.
	protected updateForm?(): void;

	// eslint-disable-next-line @angular-eslint/prefer-inject
	constructor(injector: Injector) {
		super(injector); // remove this when super class is changed
		this.initializeForm();
	}

	public ngAfterViewInit(): void {
		setTimeout(() => {
			this.populateFilterFromParams(this.route.snapshot.queryParamMap);

			setTimeout(() => {
				// Perform this on the next cycle to not accidentally fetch the data twice.
				this.route.queryParamMap.pipe(distinctUntilChanged((a, b) => JSON.stringify(a) === JSON.stringify(b))).subscribe(params => {
					this.populateFilterFromParams(params);
					this.loadItems(!this.isFirstLoad);
				});
			});
		});
	}

	public search(terms: string): void {
		this.filter.terms = terms;
		this.filter.page = 0;
		this.updateQueryParams();
	}

	public pageChanged(pageNumber: number): void {
		if (!this.isLoading) {
			this.filter.page = pageNumber;
			this.updateQueryParams();
		}
	}

	protected loadItems(scroll = false): void {
		this.isLoading = true;
		this.fetchPage(this.filter)
			.pipe(finalize(() => {
				this.doneLoading(scroll);
			})).subscribe((data) => {
				this.page = data;
			});
	}

	protected updateQueryParams(): void {
		const params = this.filterToParams(this.filter);
		void this.router.navigate([], { relativeTo: this.route, queryParams: params, queryParamsHandling: 'merge' });
	}

	protected setSearchText(terms: string | null): void {
		this.listScaffold?.setSearchText(terms);
	}

	protected deleteAndLoad(modalTitle: MessageConfig | string, modalBody: MessageConfig | string | TemplateRef<any> | undefined, deleteAction: () => Observable<any>, successMessage: MessageConfig | string): Observable<boolean | undefined> {
		return this.listScaffold!.showDeleteModal(modalTitle, modalBody, () => this.delete(deleteAction), successMessage);
	}

	// protected showDeleteModal(title: MessageConfig | string, body: MessageConfig | string | undefined, action: () => Observable<boolean>, successMessage: MessageConfig | string): Observable<boolean | undefined> {
	// 	return this.listScaffold!.showDeleteModal(title, body, action, successMessage);
	// }

	public doneLoading(scroll = false): void {
		super.doneLoading();
		this.listScaffold?.doneLoading(scroll);
	}

	private initializeForm(): void {
		this.setupForm?.();
		this.form?.valueChanges.pipe(distinctUntilChanged((a, b) => JSON.stringify(a) === JSON.stringify(b))).subscribe(value => {
			let k: keyof typeof value;
			for (k in value) {
				const v = value[k];
				(this.filter as any)[k] = v; // need cast because filter does not have an index signature
			}

			this.filter.page = 0;
			this.updateQueryParams();
		});
	}

	protected paramsToFilter(filter: Filter, params: ParamMap): void {
		params.keys.filter(key => params.get(key) !== null).forEach(key => {
			let value: null | string | number = params.get(key);
			if (value === 'null') {
				value = null;
			} else if (value && !isNaN(value as never)) {
				value = Number(value);
			}
			filter[key] = value;
		});
		this.updateForm?.();
	}

	protected filterToParams(filter: FilterType): Params {
		const params: Params = {};
		for (const [k, v] of Object.entries(filter)) {
			params[k] = v ?? 'null';
		}
		return params;
	}

	protected populateFilterFromParams(params: ParamMap) {
		this.paramsToFilter(this.filter, params);
		this.setSearchText(this.filter.terms);
	}

	protected delete(deleteAction: () => Observable<any>): Observable<boolean> {
		return deleteAction().pipe(
			map(() => {
				this.loadItems();
				return true;
			}),
			catchError(() => of(false))
		);
	}
}